.switch-buttons {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}
.switch-buttons > * {
  margin-right: 30px;
  margin-bottom: 30px;
}

.switch-btn {
  width: 54px;
  height: 32px;
  position: relative;
  cursor: pointer;
}
.switch-btn input {
  position: absolute;
  width: 100%;
  height: 100%;
  top: 0;
  left: 0;
  opacity: 0;
  z-index: 1;
  cursor: pointer;
}
.switch-btn input:checked ~ .switch-body .slide .inactive-icon {
  display: flex;
}
.switch-btn input:checked ~ .switch-body .slide {
  right: auto;
  left: 2px;
}
.switch-btn input:checked ~ .switch-body .slide .active-icon {
  display: none;
}
.switch-btn .slide {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  overflow: hidden;
  color: var(--white);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  right: 2px;
  top: 2px;
  transition: all 0.3s;
}
.switch-btn .slide .icon {
  width: 100%;
  height: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  padding: 4px;
}
.switch-btn .slide .inactive-icon {
  display: none;
  background: #e0e0e0;
  color: var(--dark-3);
}
.switch-btn .slide .active-icon {
  background: var(--primary);
